/** @format */

import { AbstractControl, Validators } from '@angular/forms';
import { ConfigForm, FormAction, FormCompletionStats, Group, TYPE_CONTROL_FORM } from './dynamic-form.interface';

/**
 * Tipi di campo esclusi dal calcolo del completamento (contenitori, non input).
 */
const SKIP_COMPLETION = new Set<TYPE_CONTROL_FORM>([TYPE_CONTROL_FORM.GROUP]);

/**
 * Riferimento "appiattito" a un singolo campo del form.
 *
 * Permette di accedere a un controllo per nome senza dover navigare manualmente
 * la struttura annidata della `ConfigForm`.
 */
export interface FlatFieldRef {
    /** Nome univoco del campo (`formAction.formName`). */
    formName: string;
    /** Controllo reattivo associato. */
    control: AbstractControl;
    /** Tipo del campo. */
    type: TYPE_CONTROL_FORM;
    /** Configurazione completa del campo. */
    formAction: FormAction;
    /** Indice del gruppo di primo livello che contiene il campo. */
    groupIndex: number;
    /** Percorso puntato dei nomi dei gruppi annidati (es. `parent.child`). */
    path: string;
}

/**
 * Appiattisce ricorsivamente tutti i campi della `ConfigForm` in una lista lineare,
 * includendo i campi annidati nei gruppi di tipo GROUP.
 *
 * @param allGroup - Configurazione del form.
 * @returns Lista di riferimenti `FlatFieldRef`, uno per ogni campo con un `formControl`.
 */
export function flattenFields(allGroup: ConfigForm | null | undefined): FlatFieldRef[] {
    const result: FlatFieldRef[] = [];
    if (!allGroup) return result;

    allGroup.forEach((group, groupIndex) => {
        for (const form of group.formGroup ?? []) {
            const fa = form?.formAction;
            if (!fa) continue;
            collectField(fa, groupIndex, '', result);
        }
    });
    return result;
}

function collectField(fa: FormAction, groupIndex: number, parentPath: string, acc: FlatFieldRef[]): void {
    const name = fa.formName ?? '';
    const path = parentPath ? `${parentPath}.${name}` : name;

    // Gruppo annidato: ricorsione sui figli (formGroup è una ConfigForm = Group[]).
    if (fa.formGroup && fa.formGroup.length) {
        for (const nestedGroup of fa.formGroup as Group[]) {
            const forms = (nestedGroup.formGroup ?? []) as any[];
            for (const child of forms) {
                const childFa = child?.formAction as FormAction | undefined;
                if (childFa) collectField(childFa, groupIndex, path, acc);
            }
        }
        return;
    }

    if (fa.formControl) {
        acc.push({
            formName: name,
            control: fa.formControl,
            type: fa.type as unknown as TYPE_CONTROL_FORM,
            formAction: fa,
            groupIndex,
            path,
        });
    }
}

function isFieldFilled(fa: FormAction): boolean {
    const value = fa.formControl?.value;
    if (value === null || value === undefined || value === '' || value === false) return false;
    if (Array.isArray(value)) return value.length > 0;
    return true;
}

function collectTrackable(allGroup: ConfigForm | null | undefined): FormAction[] {
    if (!allGroup) return [];
    const result: FormAction[] = [];
    for (const group of allGroup) {
        for (const form of group.formGroup ?? []) {
            const fa = form?.formAction;
            if (
                fa?.formControl &&
                !SKIP_COMPLETION.has(fa.type as unknown as TYPE_CONTROL_FORM) &&
                !fa.formControl.disabled
            ) {
                result.push(fa);
            }
        }
    }
    return result;
}

function computeRequiredStats(groupFas: FormAction[]): FormCompletionStats['required'] {
    const trackable = groupFas.filter(fa => !fa.formControl?.disabled);
    const reqFas = trackable.filter(fa => {
        try { return fa.formControl?.hasValidator?.(Validators.required) ?? false; }
        catch { return false; }
    });
    const reqTotal = reqFas.length;
    const reqFilled = reqFas.filter(fa => isFieldFilled(fa)).length;
    return { total: reqTotal, filled: reqFilled, percentage: reqTotal > 0 ? Math.round((reqFilled / reqTotal) * 100) : 0 };
}

/**
 * Calcola le statistiche di completamento dell'intero form a partire dalla `ConfigForm`.
 *
 * Esclude i campi disabilitati e i contenitori (GROUP). Un campo è considerato
 * "compilato" se ha un valore non vuoto (array non vuoti contano come compilati,
 * `false` di una checkbox conta come non compilato).
 *
 * @param allGroup - Configurazione del form.
 * @returns Statistiche aggregate totali, required e per gruppo.
 */
export function computeFormCompletion(allGroup: ConfigForm | null | undefined): FormCompletionStats {
    const fas = collectTrackable(allGroup);
    const total = fas.length;
    const filled = fas.filter(fa => isFieldFilled(fa)).length;
    const percentage = total > 0 ? Math.round((filled / total) * 100) : 0;
    const required = computeRequiredStats(fas);

    const groups = (allGroup ?? []).map(group => {
        const groupFas = (group.formGroup ?? [])
            .map(f => f?.formAction)
            .filter(fa => fa?.formControl && !fa.formControl.disabled && !SKIP_COMPLETION.has(fa.type as unknown as TYPE_CONTROL_FORM)) as FormAction[];
        const gTotal = groupFas.length;
        const gFilled = groupFas.filter(fa => isFieldFilled(fa)).length;
        return {
            id: group.id ?? '',
            title: group.title ?? '',
            total: gTotal,
            filled: gFilled,
            percentage: gTotal > 0 ? Math.round((gFilled / gTotal) * 100) : 0,
            required: computeRequiredStats(groupFas),
        };
    });

    return { total, filled, percentage, required, groups };
}
